/**
 * A default command plus a menu of variants (`design/components/split-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/split-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/menu'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  afresh,
  agentMember,
  agentPress,
  chooseMenuEntry,
  claimSlot,
  classes,
  createDerived,
  elementRef,
  followHighlight,
  menuChoices,
  mergeParts,
  ownerContext,
  provide,
  scope,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type Defaults,
  type IconRole,
  type LawfulVariants,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/split-button.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Kbd from '../structure/Kbd'
import SplitButtonSubmenu from './SplitButtonSubmenu'
import type { MenuEntry } from '../overlays/Menu'

export interface SplitButtonGrid {
  solid: 'accent'
  soft: 'accent'
  outline: 'neutral' | 'accent'
}

export type SplitButtonAppearance = LawfulVariants<SplitButtonGrid>

export interface SplitButtonProps {
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  /**
   * Disables the whole group, because the halves never differ.
   */
  disabled?: boolean
  /**
   * Menu entries exactly as `menu.md` defines them, with every entry kind supported.
   */
  entries: MenuEntry[]
  /**
   * A leading icon on the primary half (as in Button).
   */
  icon?: IconRole
  /**
   * The primary half's visible text, as in Button, truncated with an ellipsis on overflow.
   */
  label: string
  /**
   * Shows the spinner in the primary half's icon slot, following the conventions' loading rule,
   * and the layout stays the same. The chevron is disabled too. One running command is the whole
   * group's state, and starting a variant while it runs would be the double-submit bug Button
   * prevents, at group level.
   */
  loading?: boolean
  /**
   * The chevron half's accessible name ("More resolve options"). It is `iconOnly`, and an
   * unnamed second button would be an unexplained tab stop. Required, because the member has no
   * built-in text (as with PasswordInput's `toggleLabel`).
   */
  menuLabel: string
  /**
   * The primary half's handler. Disconnected while `loading` (Button's double-submit rule).
   */
  onClick?: (event: MouseEvent) => void
  /**
   * The menu half's presentation, as in Menu (`menu.md`; the conventions' sheet presentation).
   * `'auto'` shows the panel as a sheet below `30rem`, and `'popover'` keeps the popper. The
   * control group itself never changes, because the halves are Buttons, and Buttons have no
   * phone-specific form.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'neutral'
  variant?: 'solid' | 'soft' | 'outline'
}

/** What SplitButton hands its compound parts. */
export interface SplitButtonOwner {
  readonly api: zag.Api
  readonly service: zag.Service
}

/** A default command plus a menu of variants. */
export default function SplitButton(given: SplitButtonProps): JSX.Element {
  const props = mergeProps(
    {
      variant: 'solid',
      tone: 'accent',
      size: 'md',
      disabled: false,
      loading: false,
      presentation: 'auto',
    } as Defaults<
      SplitButtonProps,
      'variant' | 'tone' | 'size' | 'disabled' | 'loading' | 'presentation'
    >,
    claimSlot(given),
  )
  return scope(() => {
    provide(ownerContext<SplitButtonOwner>('SplitButton'), {
      get api() {
        return api.value
      },
      get service() {
        return service
      },
    })
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const primary = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const flat = createDerived(() =>
      props.entries.flatMap((entry) =>
        entry.kind === 'submenu'
          ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
          : [entry],
      ),
    )
    const documentDirection = useDirection(() => primary.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultOpen: props.defaultOpen,
          disabled: props.disabled || props.loading,
          positioning: { placement: 'bottom-end', gutter: 2 },
          onSelect: (details) => {
            flat.value.forEach(
              (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      followHighlight(panel.value, api.value.highlightedValue)
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue),
      effect1,
      true,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'SplitButton',
        element: () => primary.value,
        state: () => ({
          disabled: props.disabled,
          loading: props.loading,
          open: api.value.open,
          entries: menuChoices(props.entries),
        }),
        actions: {
          press: () => agentPress(primary.value),
          choose: {
            argument: 'id',
            run: (value) =>
              (() => {
                if (props.loading)
                  throw new Error('A command is running; its variants wait until it ends.')
                if (chooseMenuEntry(props.entries, value) && api.value.open)
                  api.value.setOpen(false)
              })(),
          },
          open: () =>
            (() => {
              if (props.loading)
                throw new Error('A command is running; its variants wait until it ends.')
              api.value.setOpen(true)
            })(),
          close: () => api.value.setOpen(false),
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <>
        {/* group */}
        <span
          class={styles.group}
          data-variant={props.variant}
          data-tone={props.tone}
          data-size={props.size}
          data-disabled={props.disabled ? '' : undefined}
          data-member="split-button"
        >
          {/* primary */}
          <button
            class={styles.primary}
            type="button"
            disabled={props.disabled}
            aria-busy={props.loading ? true : undefined}
            data-variant={props.variant}
            data-tone={props.tone}
            data-size={props.size}
            data-disabled={props.disabled ? '' : undefined}
            data-state={props.loading ? 'loading' : undefined}
            onclick={($event: MouseEvent) => !props.loading && props.onClick?.($event)}
            ref={primary.attach}
          >
            {props.loading ? (
              <span class={styles.spinner}>
                <Icon name="loading" size={props.size} />
              </span>
            ) : props.icon !== undefined ? (
              <span class={styles.glyph}>
                <Icon name={props.icon} size={props.size} />
              </span>
            ) : null}
            <span class={styles.label}>{props.label}</span>
          </button>
          <span class={styles.seam} aria-hidden="true" />
          {/* trigger */}
          <button
            {...mergeParts(api.value.getTriggerProps(), {
              class: styles.chevron,
              disabled: props.disabled || props.loading,
              'aria-label': props.menuLabel,
              'data-variant': props.variant,
              'data-tone': props.tone,
              'data-size': props.size,
              'data-disabled': props.disabled ? '' : undefined,
              'data-icon-only': '',
            })}
          >
            <Icon name="expand" size={props.size} />
          </button>
        </span>
        <Portal>
          {afresh(() => (
            <>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  {/* panel */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.content,
                      style: {
                        '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
                        '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
                      },
                      hidden: undefined,
                      'data-member': 'split-button',
                      onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                    })}
                    ref={panel.attach}
                  >
                    <Each of={props.entries} by={(_entry, index) => index} renew>
                      {(entry) => (
                        <>
                          {entry.kind === 'separator' ? (
                            <div
                              {...mergeParts(api.value.getSeparatorProps(), {
                                class: styles.separator,
                              })}
                            />
                          ) : entry.kind === 'label' ? (
                            <div class={styles.groupLabel}>{entry.label}</div>
                          ) : entry.kind === 'checkbox' ? (
                            <div
                              {...mergeParts(
                                api.value.getOptionItemProps({
                                  type: 'checkbox',
                                  value: entry.label,
                                  checked: entry.checked,
                                  disabled: entry.disabled,
                                  closeOnSelect: false,
                                  onCheckedChange: entry.onCheckedChange,
                                }),
                                {
                                  class: classes(styles.item, styles.checkbox),
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              <span class={styles.check}>
                                {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                              </span>
                              <span class={styles.rowLabel}>{entry.label}</span>
                            </div>
                          ) : entry.kind === 'submenu' ? (
                            <SplitButtonSubmenu entry={entry} />
                          ) : (
                            <div
                              {...mergeParts(
                                api.value.getItemProps({
                                  value: entry.label,
                                  disabled: entry.disabled,
                                }),
                                {
                                  class: styles.item,
                                  'data-tone': entry.tone ?? 'neutral',
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              {entry.icon !== undefined ? (
                                <span class={styles.rowGlyph}>
                                  <Icon name={entry.icon} size="sm" />
                                </span>
                              ) : null}
                              <span class={styles.rowLabel}>{entry.label}</span>
                              {entry.kbd !== undefined ? (
                                <span class={styles.hint}>
                                  <Kbd>{entry.kbd}</Kbd>
                                </span>
                              ) : null}
                            </div>
                          )}
                        </>
                      )}
                    </Each>
                  </div>
                </div>
              ) : null}
              {scrimPresent() ? (
                <div
                  class={sheet.scrim}
                  data-state={api.value.open ? 'open' : 'closed'}
                  ref={scrim.attach}
                />
              ) : null}
              {sheetPresent() ? (
                <div class={sheet.positioner}>
                  <div
                    class={sheet.panel}
                    data-presentation="sheet"
                    data-state={api.value.open ? 'open' : 'closed'}
                    tabindex="-1"
                    ref={sheetPanel.attach}
                  >
                    {/* panel */}
                    <div
                      {...mergeParts(api.value.getContentProps(), {
                        class: styles.sheetList,
                        hidden: undefined,
                        'data-member': 'split-button',
                        onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                      })}
                      ref={panel.attach}
                    >
                      <Each of={flat.value} by={(_entry, index) => index} renew>
                        {(entry) => (
                          <>
                            {entry.kind === 'separator' ? (
                              <div
                                {...mergeParts(api.value.getSeparatorProps(), {
                                  class: styles.separator,
                                })}
                              />
                            ) : entry.kind === 'label' ? (
                              <div class={styles.groupLabel}>{entry.label}</div>
                            ) : entry.kind === 'checkbox' ? (
                              <div
                                {...mergeParts(
                                  api.value.getOptionItemProps({
                                    type: 'checkbox',
                                    value: entry.label,
                                    checked: entry.checked,
                                    disabled: entry.disabled,
                                    closeOnSelect: false,
                                    onCheckedChange: entry.onCheckedChange,
                                  }),
                                  {
                                    class: classes(styles.item, styles.checkbox),
                                    tabindex: '-1',
                                    onfocus: () => api.value.setHighlightedValue(entry.label),
                                  },
                                )}
                              >
                                <span class={styles.check}>
                                  {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                                </span>
                                <span class={styles.rowLabel}>{entry.label}</span>
                              </div>
                            ) : (
                              <div
                                {...mergeParts(
                                  api.value.getItemProps({
                                    value: entry.label,
                                    disabled: entry.disabled,
                                  }),
                                  {
                                    class: styles.item,
                                    'data-tone': entry.tone ?? 'neutral',
                                    tabindex: '-1',
                                    onfocus: () => api.value.setHighlightedValue(entry.label),
                                  },
                                )}
                              >
                                {entry.icon !== undefined ? (
                                  <span class={styles.rowGlyph}>
                                    <Icon name={entry.icon} size="sm" />
                                  </span>
                                ) : null}
                                <span class={styles.rowLabel}>{entry.label}</span>
                                {entry.kbd !== undefined ? (
                                  <span class={styles.hint}>
                                    <Kbd>{entry.kbd}</Kbd>
                                  </span>
                                ) : null}
                              </div>
                            )}
                          </>
                        )}
                      </Each>
                    </div>
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
